1|use indoc::indoc;
2|
3|use liwe::find::{DocumentFinder, FindOptions};
4|use liwe::graph::Graph;
5|use liwe::model::config::MarkdownOptions;
6|use liwe::state::from_indoc;
7|
8|fn setup_graph(input: &str) -> Graph {
9|    Graph::import(&from_indoc(input), MarkdownOptions::default(), None)
10|}
11|
12|#[test]
13|fn filters_by_single_string_value() {
14|    let graph = setup_graph(indoc! {"
15|        ---
16|        title: Task A
17|        status: ready
18|        ---
19|
20|        # Task A
21|        _
22|        ---
23|        title: Task B
24|        status: done
25|        ---
26|
27|        # Task B
28|    "});
29|
30|    let finder = DocumentFinder::new(&graph);
31|    let options = FindOptions {
32|        metadata_filters: vec![("status".to_string(), "ready".to_string())],
33|        ..Default::default()
34|    };
35|    let output = finder.find(&options);
36|    assert_eq!(output.results.len(), 1);
37|    assert_eq!(output.results[0].title, "Task A");
38|}
39|
40|#[test]
41|fn combines_filters_with_and() {
42|    let graph = setup_graph(indoc! {"
43|        ---
44|        title: Note 1
45|        status: ready
46|        category: work
47|        ---
48|
49|        # Note 1
50|        _
51|        ---
52|        title: Note 2
53|        status: ready
54|        category: personal
55|        ---
56|
57|        # Note 2
58|    "});
59|
60|    let finder = DocumentFinder::new(&graph);
61|    let options = FindOptions {
62|        metadata_filters: vec![
63|            ("status".to_string(), "ready".to_string()),
64|            ("category".to_string(), "work".to_string()),
65|        ],
66|        ..Default::default()
67|    };
68|    let output = finder.find(&options);
69|    assert_eq!(output.results.len(), 1);
70|    assert_eq!(output.results[0].title, "Note 1");
71|}
72|
73|#[test]
74|fn non_matching_value_excluded() {
75|    let graph = setup_graph(indoc! {"
76|        ---
77|        title: Task A
78|        status: done
79|        ---
80|
81|        # Task A
82|    "});
83|
84|    let finder = DocumentFinder::new(&graph);
85|    let options = FindOptions {
86|        metadata_filters: vec![("status".to_string(), "ready".to_string())],
87|        ..Default::default()
88|    };
89|    let output = finder.find(&options);
90|    assert_eq!(output.results.len(), 0);
