93|#[test]
94|fn note_without_metadata_excluded() {
95|    let graph = setup_graph(indoc! {"
96|        # No Metadata
97|    "});
98|
99|    let finder = DocumentFinder::new(&graph);
100|    let options = FindOptions {
101|        metadata_filters: vec![("status".to_string(), "ready".to_string())],
102|        ..Default::default()
103|    };
104|    let output = finder.find(&options);
105|    assert_eq!(output.results.len(), 0);
106|}
107|
108|#[test]
109|fn value_in_yaml_sequence_matches() {
110|    let graph = setup_graph(indoc! {"
111|        ---
112|        title: Task A
113|        tags:
114|          - rust
115|          - iwe
116|        ---
117|
118|        # Task A
119|    "});
120|
121|    let finder = DocumentFinder::new(&graph);
122|    let options = FindOptions {
123|        metadata_filters: vec![("tags".to_string(), "rust".to_string())],
124|        ..Default::default()
125|    };
126|    let output = finder.find(&options);
127|    assert_eq!(output.results.len(), 1);
128|    assert_eq!(output.results[0].title, "Task A");
129|}
