131|#[test]
132|fn combines_with_roots_flag() {
133|    let graph = setup_graph(indoc! {"
134|        ---
135|        title: Root
136|        status: ready
137|        ---
138|
139|        # Root
140|
141|        [child](2)
142|        _
143|        ---
144|        title: Child
145|        status: ready
