45|pub struct FormattingOptions {
46|    pub emphasis_token: Option<String>,
47|    pub strong_token: Option<String>,
48|    pub list_token: Option<String>,
49|    pub ordered_list_token: Option<String>,
50|    pub code_block_token: Option<String>,
51|    pub code_block_token_count: Option<usize>,
52|    pub increment_ordered_list_bullets: Option<bool>,
53|    pub rule_token: Option<String>,
54|    pub rule_token_count: Option<usize>,
55|}
56|
57|impl FormattingOptions {
58|    pub fn validated(self) -> Self {
59|        Self {
60|            emphasis_token: self
61|                .emphasis_token
62|                .filter(|v| matches!(v.as_str(), "*" | "_")),
63|            strong_token: self
64|                .strong_token
65|                .filter(|v| matches!(v.as_str(), "**" | "__")),
66|            list_token: self
67|                .list_token
68|                .filter(|v| matches!(v.as_str(), "*" | "-" | "+")),
69|            ordered_list_token: self
70|                .ordered_list_token
71|                .filter(|v| matches!(v.as_str(), "." | ")")),
72|            code_block_token: self
73|                .code_block_token
74|                .filter(|v| matches!(v.as_str(), "`" | "~")),
75|            code_block_token_count: self.code_block_token_count.filter(|&v| v >= 3),
76|            increment_ordered_list_bullets: self.increment_ordered_list_bullets,
77|            rule_token: self
78|                .rule_token
79|                .filter(|v| matches!(v.as_str(), "-" | "*" | "_")),
80|            rule_token_count: self.rule_token_count.filter(|&v| v >= 3),
81|        }
82|    }
83|
84|    pub fn emphasis_token(&self) -> &str {
85|        self.emphasis_token.as_deref().unwrap_or("*")
86|    }
87|
88|    pub fn strong_token(&self) -> &str {
89|        self.strong_token.as_deref().unwrap_or("**")
90|    }
91|
92|    pub fn list_token(&self) -> &str {
93|        self.list_token.as_deref().unwrap_or("-")
94|    }
95|
96|    pub fn list_token_char(&self) -> char {
97|        self.list_token().chars().next().unwrap_or('-')
98|    }
99|
100|    pub fn ordered_list_token(&self) -> &str {
101|        self.ordered_list_token.as_deref().unwrap_or(".")
102|    }
103|
104|    pub fn ordered_list_token_char(&self) -> char {
105|        self.ordered_list_token().chars().next().unwrap_or('.')
106|    }
107|
108|    pub fn code_block_token(&self) -> &str {
109|        self.code_block_token.as_deref().unwrap_or("`")
110|    }
111|
112|    pub fn code_block_token_char(&self) -> char {
113|        self.code_block_token().chars().next().unwrap_or('`')
114|    }
115|
116|    pub fn code_block_token_count(&self) -> usize {
117|        self.code_block_token_count.unwrap_or(3)
118|    }
